/**
 * Error type returned by all FFI functions.
 *
 * Variants are designed for programmatic matching on the Swift/Kotlin side.
 * Each carries enough context for the host to decide on UX (retry, show
 * message, refresh cache, etc.) without parsing strings.
 */
public enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The referenced task does not exist.
     */
    case TaskNotFound(uuid: String
    )
    /**
     * A task with this UUID already exists (create collision).
     */
    case TaskAlreadyExists(uuid: String
    )
    /**
     * Caller-side validation error (bad UUID format, invalid tag, etc.).
     */
    case InvalidInput(message: String
    )
    /**
     * Storage-layer error (SQL execution failure, connection issue).
     */
    case Storage(message: String
    )
    /**
     * Unexpected internal error (bug, catch-all).
     */
    case Internal(message: String
    )
    /**
     * Reparent would create a cycle (uuid cannot be a descendant of parent).
     */
    case CircularParent(uuid: String, parent: String
    )
    /**
     * Reorder anchor is not under the same parent as the task.
     */
    case NotASibling(uuid: String, anchor: String
    )
    /**
     * Reorder/reparent anchor exists in the DB but has no position field.
     *
     * Use a positioned task as anchor, or call `SetPosition` first.
     */
    case AnchorHasNoPosition(uuid: String
    )
    /**
     * delete_tag / rename_tag on a tag name not present in tc_config.
     */
    case TagNotFound(name: String
    )
    /**
     * rename_tag target already exists in tc_config.
     */
    case TagAlreadyExists(name: String
    )
    /**
     * set_xstatus with a name not in tc_config.xstatus definitions.
     */
    case UnknownXStatus(name: String
    )
    /**
     * delete_xstatus / rename_xstatus on a name not present in tc_config.xstatus.
     */
    case XStatusNotFound(name: String
    )
    /**
     * rename_xstatus / create_xstatus target already exists in tc_config.xstatus.
     */
    case XStatusAlreadyExists(name: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .TaskNotFound(
            uuid: try FfiConverterString.read(from: &buf)
            )
        case 2: return .TaskAlreadyExists(
            uuid: try FfiConverterString.read(from: &buf)
            )
        case 3: return .InvalidInput(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Storage(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .CircularParent(
            uuid: try FfiConverterString.read(from: &buf), 
            parent: try FfiConverterString.read(from: &buf)
            )
        case 7: return .NotASibling(
            uuid: try FfiConverterString.read(from: &buf), 
            anchor: try FfiConverterString.read(from: &buf)
            )
        case 8: return .AnchorHasNoPosition(
